def sh(cmd, timeout=None, check=True):
    print("$", cmd if len(cmd) < 300 else cmd[:300] + " ...", flush=True)
    r = subprocess.run(cmd, shell=True, text=True, capture_output=True, timeout=timeout)
    if r.stdout.strip():
        print(r.stdout[-2500:])
    if r.returncode:
        print(r.stderr[-4000:])
        if check:
            raise RuntimeError(f"command failed ({r.returncode})")
    return r.stdout


def sha1_text(s):
    return hashlib.sha1(s.encode("utf-8")).hexdigest()


