# %% [markdown]
# ## The training index
#
# `dec_split == "train"` only. `dec_val` and every `heldout_*` label are the model's **exclusion
# set**, not merely an eval holdout.

# %%
t0 = time.time()
META = pq.read_table(DOUT / "corpus_meta.parquet",
                     columns=["inchikey14", "adduct", "precursor_mz", "molecular_formula"]).to_pandas()
assert len(META) == N_CORPUS_ROWS, len(META)
META["inchikey14"] = META.inchikey14.astype(str)
META["adduct"] = META.adduct.astype(str)
META["molecular_formula"] = META.molecular_formula.astype(str)
CE = pq.read_table(P0 / "corpus_ce.parquet", columns=["row", "n_ce", "ce_mean"]).to_pandas()
assert len(CE) == N_CORPUS_ROWS and (CE.row.to_numpy() == np.arange(N_CORPUS_ROWS)).all()
CE["ce_mean"] = np.where(CE.n_ce.to_numpy() > 0, CE.ce_mean.to_numpy(np.float64), np.nan)
SPLIT = pd.read_parquet(P1 / "dec_split.parquet")
SPLIT["inchikey14"] = SPLIT.inchikey14.astype(str)
print("split labels:", SPLIT.split.value_counts().to_dict())
print(f"loaded corpus in {time.time() - t0:.0f}s")


def get_index(name, keep):
    path = OUT / f"index_{name}.npz"
    if path.exists():
        idx = p3d.Index.load(path)
        print(f"index[{name}]: loaded {len(idx):,} molecules / {idx.meta['n_rows']:,} rows")
        return idx
    t = time.time()
    idx = p3d.build_index(META, CE, SPLIT, ST, VOCAB, keep_splits=keep)
    idx.save(path)
    print(f"index[{name}]: built {len(idx):,} molecules / {idx.meta['n_rows']:,} rows "
          f"in {time.time() - t:.0f}s -> {path}")
    return idx


IDX = get_index("train", ("train",))
VAL = get_index("dec_val", ("dec_val",))

# the exclusion set is the model's TRAINING set: assert it, do not trust it
train_ik = set(SPLIT.loc[SPLIT.split == "train", "inchikey14"])
assert set(IDX.ik14) <= train_ik, "a non-train molecule reached the training index"
assert not (set(VAL.ik14) & set(IDX.ik14)), "dec_val leaked into train"
held = set(SPLIT.loc[SPLIT.split.isin(("heldout_c3", "heldout_ts", "heldout_c2")), "inchikey14"])
assert not (set(IDX.ik14) & held), "a held-out cohort molecule reached the training index"
print(f"exclusion checks OK: train {len(IDX):,}, dec_val {len(VAL):,}, held out {len(held):,}")

STORE = p3d.EmbeddingStore(EMB, n_rows=N_CORPUS_ROWS)
print(f"embeddings: {len(STORE.parts)} chunks, {STORE.n_rows:,} rows, dim {STORE.dim}")
LENGTHS = np.diff(IDX.tok_off)
SPEC_PER_MOL = np.diff(IDX.row_off)
GATE["index"] = dict(train_molecules=len(IDX), train_rows=int(IDX.row_off[-1]),
                     dec_val_molecules=len(VAL), dec_val_rows=int(VAL.row_off[-1]),
                     tok_len_p50=float(np.median(LENGTHS)), tok_len_max=int(LENGTHS.max()),
                     spec_per_mol_p50=float(np.median(SPEC_PER_MOL)),
                     spec_per_mol_mean=float(SPEC_PER_MOL.mean()),
                     ce_known_share=float((IDX.row_ce != nd.CE_UNKNOWN).mean()))
