# %% [markdown]
# ## Model

# %%
torch.manual_seed(SEED)
MODEL = nd.DreamsSelfiesDecoder(len(VOCAB), pad_id=VOCAB.pad_id, sos_id=VOCAB.sos_id,
                                eos_id=VOCAB.eos_id, d_model=D_MODEL, n_layers=N_LAYERS,
                                n_heads=N_HEADS, d_ff=D_FF, dropout=DROPOUT, max_len=MAX_LEN).to(DEV)
N_PAR = sum(p.numel() for p in MODEL.parameters())
STEPS_PER_EPOCH = math.ceil(len(IDX) / BATCH)
OPT = torch.optim.AdamW(MODEL.parameters(), lr=LR, betas=(0.9, 0.95), weight_decay=0.01)


def lr_at(step):
    if step < WARMUP:
        return LR * (step + 1) / WARMUP
    total = COSINE_EPOCHS * STEPS_PER_EPOCH
    frac = min(1.0, (step - WARMUP) / max(1, total - WARMUP))
    return LR * (LR_MIN_FRAC + (1 - LR_MIN_FRAC) * 0.5 * (1 + math.cos(math.pi * frac)))


SCHED = torch.optim.lr_scheduler.LambdaLR(OPT, lambda s: lr_at(s) / LR)
GATE["model"] = dict(params=N_PAR, d_model=D_MODEL, n_layers=N_LAYERS, n_heads=N_HEADS, d_ff=D_FF,
                     dropout=DROPOUT, batch=BATCH, lr=LR, warmup=WARMUP,
                     cosine_epochs=COSINE_EPOCHS, steps_per_epoch=STEPS_PER_EPOCH,
                     max_spec_per_mol=MAX_SPEC_PER_MOL, ce_dropout=CE_DROPOUT, seed=SEED)
print(f"{N_PAR:,} parameters; {STEPS_PER_EPOCH} steps per epoch")
print(GATE["model"])

# %% [markdown]
# ## Batching, loss, and the fixed `dec_val` set
#
# `dec_val` batches are built **once**, with fixed spectra and CE dropout off. G3.2 is "no `dec_val`
# improvement for 5 epochs", so the signal must not wobble because the val set was resampled.

# %%
def to_dev(b):
    out = {}
    for k, v in b.items():
        t = torch.from_numpy(v)
        out[k] = t.to(DEV, non_blocking=True)
    return out


def batch_loss(b):
    """Teacher-forced cross-entropy on SELFIES, given the true formula. -> (loss, n_tok, n_correct)"""
    mem, pad = MODEL.build_memory(b["emb"], b["adduct"], b["ce"], b["fvec"], b["spec_mask"])
    tgt = b["tgt"]
    logits = MODEL(tgt[:, :-1], mem, pad)
    gold = tgt[:, 1:]
    loss = torch.nn.functional.cross_entropy(
        logits.reshape(-1, logits.shape[-1]).float(), gold.reshape(-1),
        ignore_index=VOCAB.pad_id)
    with torch.no_grad():
        keep = gold != VOCAB.pad_id
        correct = ((logits.argmax(-1) == gold) & keep).sum()
    return loss, int(keep.sum()), int(correct)


VRNG = np.random.default_rng(SEED + 1)
VAL_ORDER = p3d.epoch_order(len(VAL), VRNG, BATCH, np.diff(VAL.tok_off))[:VAL_BATCHES]
VAL_BATCH = [p3d.make_batch(VAL, ids, STORE, np.random.default_rng(SEED + 100 + i),
                            max_spec=MAX_SPEC_PER_MOL, ce_dropout=0.0, pad_id=VOCAB.pad_id,
                            sos_id=VOCAB.sos_id, eos_id=VOCAB.eos_id)
             for i, ids in enumerate(VAL_ORDER)]
print(f"dec_val: {len(VAL_BATCH)} fixed batches, "
      f"{sum(len(b['tgt']) for b in VAL_BATCH):,} molecules, CE dropout off")


@torch.no_grad()
def evaluate():
    MODEL.eval()
    tot, ntok, ncor = 0.0, 0, 0
    for b in VAL_BATCH:
        d = to_dev(b)
        with torch.autocast("cuda", dtype=torch.bfloat16, enabled=BF16):
            loss, nt, nc = batch_loss(d)
        tot += float(loss) * nt
        ntok += nt
        ncor += nc
    MODEL.train()
    return tot / max(ntok, 1), ncor / max(ntok, 1)

# %% [markdown]
# ## Checkpointing: every epoch, atomically, on Drive
#
# The RNG states are part of the checkpoint. Without them a resumed run samples a different stream of
# spectra and CE dropouts, so "epoch 12" would not mean the same thing before and after a
# disconnect — and G3.2 counts epochs.

# %%
EPOCH_RNG = np.random.default_rng(SEED)


def rng_state():
    return dict(torch=torch.get_rng_state(),
                cuda=torch.cuda.get_rng_state_all(),
                numpy=EPOCH_RNG.bit_generator.state,
                python=random.getstate())


def set_rng_state(s):
    torch.set_rng_state(s["torch"].cpu() if hasattr(s["torch"], "cpu") else s["torch"])
    try:
        torch.cuda.set_rng_state_all(s["cuda"])
    except Exception as e:                        # a different GPU count on the resumed machine
        print(f"[WARN] could not restore the CUDA RNG state ({e}); continuing")
    EPOCH_RNG.bit_generator.state = s["numpy"]
    random.setstate(s["python"])


def atomic_save(obj, dest):
    """Write beside the destination on the SAME filesystem, then rename. A disconnect part-way
    through must never leave a truncated file where a loadable checkpoint used to be."""
    tmp = Path(str(dest) + ".tmp")
    torch.save(obj, tmp)
    os.replace(tmp, dest)


def log_epoch(rec):
    """Append-only, flushed: the per-epoch numbers survive even a failed checkpoint write."""
    with open(OUT / "train_log.jsonl", "a") as f:
        f.write(json.dumps(rec) + "\n")
        f.flush()
        os.fsync(f.fileno())


def save_decoder(epoch, val_loss):
    """The artefact P4/P5 load: best-so-far weights only, no optimizer state."""
    atomic_save(dict(state_dict={k: v.to("cpu") for k, v in MODEL.state_dict().items()},
                     hparams=MODEL.hparams, vocab_sha1=vsha, vocab_size=len(VOCAB),
                     adducts=list(nd.TEST_ADDUCTS), ce_bins=list(nd.CE_BINS),
                     max_len=MAX_LEN, epoch=epoch, dec_val_loss=val_loss,
                     src_sha1=SRC_SHA1, seed=SEED), OUT / "decoder.pt")


def save_ckpt(epoch, step, best, patience, history):
    atomic_save(dict(epoch=epoch, step=step, best=best, patience=patience, history=history,
                     model=MODEL.state_dict(), opt=OPT.state_dict(), sched=SCHED.state_dict(),
                     rng=rng_state(), hparams=MODEL.hparams),
                CKPT / f"epoch_{epoch:03d}.pt")
    keep = sorted(CKPT.glob("epoch_*.pt"))[-2:]   # rotate: ~340 MB each with the optimizer state
    for old in sorted(CKPT.glob("epoch_*.pt")):
        if old not in keep:
            old.unlink()


def load_latest():
    """Highest epoch that actually loads; a truncated newest file falls back to the one before."""
    for p in sorted(CKPT.glob("epoch_*.pt"), reverse=True):
        try:
            c = torch.load(p, map_location=DEV, weights_only=False)
        except Exception as e:
            print(f"[WARN] {p.name} will not load ({type(e).__name__}); trying the previous one")
            continue
        MODEL.load_state_dict(c["model"])
        OPT.load_state_dict(c["opt"])
        SCHED.load_state_dict(c["sched"])
        set_rng_state(c["rng"])
        return c
    return None


CK = load_latest()
if CK is None:
    START, STEP, BEST, PAT, HIST = 0, 0, float("inf"), 0, []
    print("=" * 88)
    print("STARTING FRESH -- no checkpoint under " + str(CKPT))
    print("=" * 88)
else:
    START, STEP = CK["epoch"] + 1, CK["step"]
    BEST, PAT, HIST = CK["best"], CK["patience"], CK["history"]
    print("=" * 88)
    print(f"RESUMED FROM EPOCH {CK['epoch']}  (next epoch {START}, step {STEP}, "
          f"best dec_val {BEST:.5f}, patience {PAT}/{PATIENCE})")
    print("=" * 88)

# %% [markdown]
# ## Calibration: time 50 steps and project the run before committing the budget

# %%
N_CAL = 52
CAL_WARMUP = 2                                   # the first steps pay for cuDNN autotuning
crng = np.random.default_rng(SEED + 999)
CAL = p3d.epoch_order(len(IDX), crng, BATCH, LENGTHS)[:N_CAL] if START == 0 else []
if START == 0 and len(CAL) <= CAL_WARMUP:
    # too few batches to time anything; skip rather than divide by zero, and leave the freshly
    # initialised model untouched so no re-init is needed below
    print(f"only {len(CAL)} batches available -- skipping calibration")
    CAL = []
if CAL:
    MODEL.train()
    cal = CAL
    t0 = None
    for i, ids in enumerate(cal):
        b = to_dev(p3d.make_batch(IDX, ids, STORE, crng, max_spec=MAX_SPEC_PER_MOL,
                                  ce_dropout=CE_DROPOUT, pad_id=VOCAB.pad_id,
                                  sos_id=VOCAB.sos_id, eos_id=VOCAB.eos_id))
        with torch.autocast("cuda", dtype=torch.bfloat16, enabled=BF16):
            loss, _, _ = batch_loss(b)
        OPT.zero_grad(set_to_none=True)
        loss.backward()
        torch.nn.utils.clip_grad_norm_(MODEL.parameters(), GRAD_CLIP)
        OPT.step()
        if i == CAL_WARMUP - 1:                   # start the clock after the warmup steps
            torch.cuda.synchronize()
            t0 = time.time()
    torch.cuda.synchronize()
    per_step = (time.time() - t0) / (len(cal) - CAL_WARMUP)
    t_ck = time.time()
    save_ckpt(-1, 0, float("inf"), 0, [])
    t_ck = time.time() - t_ck
    (CKPT / "epoch_-01.pt").unlink(missing_ok=True)
    epoch_s = per_step * STEPS_PER_EPOCH + t_ck
    GATE["calibration"] = dict(per_step_s=per_step, checkpoint_s=t_ck, epoch_s=epoch_s,
                               projected_h_40=40 * epoch_s / 3600)
    print(f"{per_step * 1000:.0f} ms/step  ->  {epoch_s / 60:.1f} min/epoch "
          f"(incl. {t_ck:.0f}s checkpoint)")
    print(f"projected: 20 epochs {20 * epoch_s / 3600:.2f} h, 40 epochs {40 * epoch_s / 3600:.2f} h")
    print(f"at ~11.8 CU/h on A100 that is ~{40 * epoch_s / 3600 * 11.8:.0f} CU for 40 epochs")
    print("\nP3's budget is ~50-60 CU. If the projection above is far over that, stop and "
          "reduce COSINE_EPOCHS / MAX_EPOCHS rather than letting it run.")
    # the calibration mutated the model and the optimizer: start the real run from scratch
    torch.manual_seed(SEED)
    MODEL = nd.DreamsSelfiesDecoder(len(VOCAB), pad_id=VOCAB.pad_id, sos_id=VOCAB.sos_id,
                                    eos_id=VOCAB.eos_id, d_model=D_MODEL, n_layers=N_LAYERS,
                                    n_heads=N_HEADS, d_ff=D_FF, dropout=DROPOUT,
                                    max_len=MAX_LEN).to(DEV)
    OPT = torch.optim.AdamW(MODEL.parameters(), lr=LR, betas=(0.9, 0.95), weight_decay=0.01)
    SCHED = torch.optim.lr_scheduler.LambdaLR(OPT, lambda s: lr_at(s) / LR)
    EPOCH_RNG = np.random.default_rng(SEED)
    print("\nmodel and optimizer re-initialised after calibration")
save_gate()

# %% [markdown]
# ## Train

# %%
MODEL.train()
t_start = time.time()
stop_reason = "max_epochs"
for epoch in range(START, MAX_EPOCHS):
    te = time.time()
    order = p3d.epoch_order(len(IDX), EPOCH_RNG, BATCH, LENGTHS)
    run, ntok, ncor = 0.0, 0, 0
    for ids in order:
        b = to_dev(p3d.make_batch(IDX, ids, STORE, EPOCH_RNG, max_spec=MAX_SPEC_PER_MOL,
                                  ce_dropout=CE_DROPOUT, pad_id=VOCAB.pad_id,
                                  sos_id=VOCAB.sos_id, eos_id=VOCAB.eos_id))
        with torch.autocast("cuda", dtype=torch.bfloat16, enabled=BF16):
            loss, nt, nc = batch_loss(b)
        OPT.zero_grad(set_to_none=True)
        loss.backward()
        torch.nn.utils.clip_grad_norm_(MODEL.parameters(), GRAD_CLIP)
        OPT.step()
        SCHED.step()
        STEP += 1
        run += float(loss) * nt
        ntok += nt
        ncor += nc
    tr_loss, tr_acc = run / max(ntok, 1), ncor / max(ntok, 1)
    va_loss, va_acc = evaluate()
    improved = va_loss < BEST - 1e-6
    if improved:
        BEST, PAT = va_loss, 0
        save_decoder(epoch, va_loss)
    else:
        PAT += 1
    rec = dict(epoch=epoch, step=STEP, train_loss=tr_loss, train_acc=tr_acc, dec_val_loss=va_loss,
               dec_val_acc=va_acc, lr=SCHED.get_last_lr()[0], seconds=time.time() - te,
               cum_hours=(time.time() - t_start) / 3600, best=BEST, patience=PAT,
               improved=bool(improved))
    HIST.append(rec)
    log_epoch(rec)
    save_ckpt(epoch, STEP, BEST, PAT, HIST)
    print(f"epoch {epoch:3d}  train {tr_loss:.5f}/{tr_acc:.4f}  dec_val {va_loss:.5f}/{va_acc:.4f}"
          f"  lr {rec['lr']:.2e}  {rec['seconds'] / 60:5.1f} min  "
          f"{'*best*' if improved else f'patience {PAT}/{PATIENCE}'}", flush=True)
    if PAT >= PATIENCE:
        stop_reason = "early_stop"
        break

# %% [markdown]
# ## Report
#
# **G3.2** (pre-registered): converged means `dec_val` token CE did not improve for 5 consecutive
# epochs **and** the best epoch is not the last. Both are printed below; record them in
# `gate_report.md`.

# %%
best_epoch = min(HIST, key=lambda r: r["dec_val_loss"])["epoch"] if HIST else None
last_epoch = HIST[-1]["epoch"] if HIST else None
g32 = bool(stop_reason == "early_stop" and best_epoch is not None and best_epoch != last_epoch)
GATE.update(training=dict(epochs_run=len(HIST), stop_reason=stop_reason, best_epoch=best_epoch,
                          last_epoch=last_epoch, best_dec_val_loss=BEST,
                          best_dec_val_acc=max((r["dec_val_acc"] for r in HIST), default=None),
                          total_hours=(time.time() - t_start) / 3600,
                          g32_converged=g32),
            finished=time.strftime("%Y-%m-%d %H:%M"))
save_gate()

print("=" * 88)
print(f"P3 TRAINING DONE -- stop reason: {stop_reason}")
print("=" * 88)
print(f"epochs run              {len(HIST)}  (from epoch {START})")
print(f"best dec_val loss       {BEST:.5f} at epoch {best_epoch}")
print(f"last epoch              {last_epoch}")
print(f"wall clock this session {(time.time() - t_start) / 3600:.2f} h")
if GATE.get("calibration"):
    print(f"projected CU (A100)     ~{(time.time() - t_start) / 3600 * 11.8:.0f}")
print()
print(f"G3.2 (converged: patience {PATIENCE} reached AND best epoch != last epoch): "
      f"{'PASS' if g32 else 'NOT MET'}")
if not g32:
    print("  -> G3.2 is not met. Per gate_report.md G3 decision rule 3 this is NOT a pass: re-run "
          "this notebook to continue from the last checkpoint until patience is reached. That is a "
          "continuation of the same run and needs no amendment.")
print()
print(f"decoder.pt   {OUT / 'decoder.pt'}")
print(f"checkpoints  {CKPT} ({len(list(CKPT.glob('epoch_*.pt')))} kept)")
print(f"log          {OUT / 'train_log.jsonl'}")
print(f"meta         {OUT / 'train_meta.json'}")
print("\nNext: casmi_novel_p3_eval_colab.ipynb (GPU) for the bake-off, then "
      "casmi_novel_p3_null_colab.ipynb (CPU) for RandomDeNovo, MCES and the G3 verdict.")
